package com.crm.invoice.entity;import jakarta.persistence.*;import lombok.Data;import java.time.*;import java.math.BigDecimal;
@Entity @Table(name="invoice_reconciliations") @Data public class InvoiceReconciliation {@Id @Column(length=36) private String id;@Column(name="customer_id",nullable=false,length=50,updatable=false) private String customerId;@Column(nullable=false,length=3,updatable=false) private String currency;@Column(name="fee_ids",nullable=false,length=600,updatable=false) private String feeIds;@Column(name="issue_date",nullable=false,updatable=false) private LocalDate issueDate;@Column(name="due_date",nullable=false,updatable=false) private LocalDate dueDate;@Column(precision=12,scale=2,updatable=false) private BigDecimal tax;@Column(nullable=false,length=30) private String state="IN_PROGRESS";@Column(name="invoice_id",unique=true) private Long invoiceId;@Column(name="error_status") private Integer errorStatus;@Column(length=500) private String outcome;@Column(name="created_by",nullable=false,updatable=false) private Long createdBy;@Column(name="created_at",nullable=false,updatable=false) private LocalDateTime createdAt;@Column(name="updated_at",nullable=false) private LocalDateTime updatedAt;@PrePersist void created(){createdAt=LocalDateTime.now();updatedAt=createdAt;}@PreUpdate void updated(){updatedAt=LocalDateTime.now();}}
